1	/**
2	 * Módulo de tracing — helpers para criar spans OpenTelemetry.
3	 *
4	 * withTrace() para funções assíncronas e withTraceSync() para síncronas.
5	 * Quando desabilitado, simplesmente executa a função sem overhead.
6	 *
7	 * Uso:
8	 *   import { withTrace } from '@/shared/lib/telemetry/tracer';
9	 *   const result = await withTrace('auth.signIn', async (span) => { ... });
10	 */
11	
12	import type { Span, Tracer } from '@opentelemetry/api';
13	import { isInitialized, getTelemetryConfig } from './telemetry';
14	
15	// ---------------------------------------------------------------------------
16	// Estado do módulo
17	// ---------------------------------------------------------------------------
18	
19	let _tracer: Tracer | null = null;
20	
21	async function getTracer(): Promise<Tracer | null> {
22	  if (_tracer) return _tracer;
23	  if (!isInitialized() || !getTelemetryConfig().enabled) return null;
24	
25	  const { trace } = await import('@opentelemetry/api');
26	  const config = getTelemetryConfig();
27	  _tracer = trace.getTracer(config.serviceName, config.serviceVersion);
28	  return _tracer;
29	}
30	
31	function getTracerSync(): Tracer | null {
32	  return _tracer;
33	}
34	
35	// ---------------------------------------------------------------------------
36	// Helpers
37	// ---------------------------------------------------------------------------
38	
39	/**
40	 * Executa uma função assíncrona dentro de um span OpenTelemetry.
41	 * Se a telemetria estiver desabilitada, executa a função diretamente.
42	 */
43	export async function withTrace<T>(
44	  name: string,
45	  fn: (span: Span | null) => Promise<T>,
46	  attrs?: Record<string, string>,
47	): Promise<T> {
48	  const tracer = await getTracer();
49	  if (!tracer) return fn(null);
50	
51	  return tracer.startActiveSpan(name, async (span) => {
52	    if (attrs) {
53	      for (const [key, value] of Object.entries(attrs)) {
54	        span.setAttribute(key, value);
55	      }
56	    }
57	    try {
58	      const result = await fn(span);
59	      span.setStatus({ code: 1 }); // OK
60	      return result;
61	    } catch (error) {
62	      span.setStatus({ code: 2, message: String(error) }); // ERROR
63	      span.recordException(error instanceof Error ? error : new Error(String(error)));
64	      throw error;
65	    } finally {
66	      span.end();
67	    }
68	  });
69	}
70	
71	/**
72	 * Executa uma função síncrona dentro de um span OpenTelemetry.
73	 * Se a telemetria estiver desabilitada, executa a função diretamente.
74	 */
75	export function withTraceSync<T>(
76	  name: string,
77	  fn: (span: Span | null) => T,
78	  attrs?: Record<string, string>,
79	): T {
80	  const tracer = getTracerSync();
81	  if (!tracer) return fn(null);
82	
83	  return tracer.startActiveSpan(name, (span) => {
84	    if (attrs) {
85	      for (const [key, value] of Object.entries(attrs)) {
86	        span.setAttribute(key, value);
87	      }
88	    }
89	    try {
90	      const result = fn(span);
91	      span.setStatus({ code: 1 }); // OK
92	      return result;
93	    } catch (error) {
94	      span.setStatus({ code: 2, message: String(error) }); // ERROR
95	      span.recordException(error instanceof Error ? error : new Error(String(error)));
96	      throw error;
97	    } finally {
98	      span.end();
99	    }
100	  });
101	}
